const MENU_DEF=[{v:'home',i:'🏠',l:'Accueil'},{v:'matieres',i:'📚',l:'Matières'},{v:'programme',i:'🗓️',l:'Programme'},{v:'stats',i:'📈',l:'Stats'},{v:'profile',i:'👤',l:'Profil'}];
