 let ok;if(r.l===0||r.l===1)ok=r.l===1;else if(typeof r.last==='boolean'||r.last===0||r.last===1)ok=!!r.last;else if(typeof r.lastOk==='boolean')ok=r.lastOk;else if(typeof r.lastCorrect==='boolean')ok=r.lastCorrect;else if(typeof r.ok==='boolean')ok=r.ok;else if(typeof r.correct==='boolean')ok=r.correct;
 const dt=v=>typeof v==='number'&&isFinite(v)?v:(typeof v==='string'&&/^\d{4}-\d{2}-\d{2}/.test(v)?Date.parse(v.length===10?v+'T12:00:00Z':v):undefined);let t=dt(r.t);if(!t)t=dt(r.ts);if(!t)t=dt(r.lastSeenAt);if(!t)t=dt(r.d);
