   if(S&&S.onb){const nm=String(S.name||'').trim().split(/\s+/);await RIC.rpc('maj_mon_profil',{p_prenom:nm[0]||'',p_nom:nm.slice(1).join(' '),p_filiere:S.fil?filBase(S.fil):'',p_annee:S.niv||'',p_programme:null}).catch(()=>{})}
